use std::collections::HashSet;

// Removes duplicates from the input vector `nums`
// Returns a new Vec with no duplicates and the same set of elements as the input.
// The order of first occurrences is preserved.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    for num in nums {
        // Insert returns true if the value was not already present.
        if seen.insert(num) {
            result.push(num);
        }
    }

    result
}

